package src

// shimFrameworkStub is generated when the provider has no plugin-framework component
// (or no framework entry point was found) so the main shim template always compiles.
const shimFrameworkStub = `package main

// generated by tfschemaex - this provider has no plugin-framework component
// (or none was detected). safe to delete.

import (
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

func frameworkJSON(_ *schema.Provider) map[string]any { return nil }
`

// shimFrameworkTemplate walks the plugin-framework side of a muxed provider entirely
// via reflection: the framework's optional interfaces (ProviderWithFunctions,
// ProviderWithEphemeralResources, ...) vary by framework version, so methods are looked
// up by name instead of asserted, and schemas are walked generically - which also
// surfaces validator/plan-modifier/default internals (including unexported fields, read
// via unsafe) that the plugin protocol never exposes. RequiresReplace plan modifiers
// are folded into a force_new flag to mirror the SDKv2 side.
const shimFrameworkTemplate = `package main

// generated by tfschemaex - walks the plugin-framework provider in-process and dumps
// its schemas as JSON. safe to delete.

import (
	"context"
	"fmt"
	"os"
	"reflect"
	"strings"
	"unsafe"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"

	fwentry "__FW_ENTRY_PACKAGE__"
)

var fwCtxV = reflect.ValueOf(context.Background())

func frameworkJSON(p *schema.Provider) (out map[string]any) {
	_ = p
	defer func() {
		if r := recover(); r != nil {
			fmt.Fprintf(os.Stderr, "shim: framework walk panicked (framework portion skipped): %v\n", r)
			out = nil
		}
	}()

	__FW_CALL__
	prov := reflect.ValueOf(fwp)
	out = map[string]any{}

	provName := ""
	if resp, ok := fwInvoke(prov, "Metadata", ""); ok {
		provName = resp.FieldByName("TypeName").String()
		out["name"] = provName
	}
	if resp, ok := fwInvoke(prov, "Schema", ""); ok {
		out["provider"] = fwWalk(resp.FieldByName("Schema"), 0)
	}

	for method, key := range map[string]string{
		"Resources":          "resources",
		"DataSources":        "data_sources",
		"EphemeralResources": "ephemeral_resources",
		"ListResources":      "list_resources",
		"Actions":            "actions",
	} {
		col := map[string]any{}
		for _, inst := range fwFactories(prov, method) {
			name := ""
			if resp, ok := fwInvoke(inst, "Metadata", provName); ok {
				if f := resp.FieldByName("TypeName"); f.IsValid() {
					name = f.String()
				}
			}
			if name == "" {
				name = fmt.Sprintf("%T", inst.Interface())
			}

			entry := map[string]any{}
			if resp, ok := fwInvoke(inst, "Schema", provName); ok {
				if v := fwWalk(resp.FieldByName("Schema"), 0); v != nil {
					entry["schema"] = v
				}
			}
			if resp, ok := fwInvoke(inst, "IdentitySchema", provName); ok {
				if v := fwWalk(resp.FieldByName("IdentitySchema"), 0); v != nil {
					entry["identity"] = v
				}
			}
			col[name] = entry
		}
		if len(col) > 0 {
			out[key] = col
		}
	}

	fns := map[string]any{}
	for _, inst := range fwFactories(prov, "Functions") {
		name := ""
		if resp, ok := fwInvoke(inst, "Metadata", provName); ok {
			if f := resp.FieldByName("Name"); f.IsValid() {
				name = f.String()
			}
		}
		if name == "" {
			name = fmt.Sprintf("%T", inst.Interface())
		}
		def := map[string]any{}
		if resp, ok := fwInvoke(inst, "Definition", provName); ok {
			if v, ok := fwWalk(resp.FieldByName("Definition"), 0).(map[string]any); ok {
				def = v
			}
		}
		fns[name] = def
	}
	if len(fns) > 0 {
		out["functions"] = fns
	}

	return out
}

// fwInvoke calls a framework-style method: Method(ctx, Request, *Response). The request
// gets ProviderTypeName set when it has such a field; the response struct is returned.
func fwInvoke(v reflect.Value, method, providerTypeName string) (reflect.Value, bool) {
	if v.Kind() == reflect.Interface {
		v = v.Elem()
	}
	m := v.MethodByName(method)
	if !m.IsValid() || m.Type().NumIn() != 3 || m.Type().In(2).Kind() != reflect.Ptr {
		return reflect.Value{}, false
	}

	req := reflect.New(m.Type().In(1)).Elem()
	if f := req.FieldByName("ProviderTypeName"); f.IsValid() && f.CanSet() && f.Kind() == reflect.String {
		f.SetString(providerTypeName)
	}
	resp := reflect.New(m.Type().In(2).Elem())
	m.Call([]reflect.Value{fwCtxV, req, resp})

	return resp.Elem(), true
}

// fwFactories calls Method(ctx) []func() T and instantiates each factory, unwrapping
// the interface so concrete-type-only methods (IdentitySchema, ...) stay reachable.
func fwFactories(prov reflect.Value, method string) []reflect.Value {
	if prov.Kind() == reflect.Interface {
		prov = prov.Elem()
	}
	m := prov.MethodByName(method)
	if !m.IsValid() || m.Type().NumIn() != 1 || m.Type().NumOut() != 1 || m.Type().Out(0).Kind() != reflect.Slice {
		return nil
	}

	factories := m.Call([]reflect.Value{fwCtxV})[0]
	out := make([]reflect.Value, 0, factories.Len())
	for i := range factories.Len() {
		fn := factories.Index(i)
		if fn.Kind() != reflect.Func || fn.IsNil() {
			continue
		}
		inst := fn.Call(nil)[0]
		if inst.Kind() == reflect.Interface {
			inst = inst.Elem()
		}
		if inst.IsValid() {
			out = append(out, inst)
		}
	}
	return out
}

var fwStringerT = reflect.TypeOf((*fmt.Stringer)(nil)).Elem()

var fwContextT = reflect.TypeOf((*context.Context)(nil)).Elem()

// fwWalk generically converts framework schema structures to JSON-friendly values:
// attr.Type values render via String(), describable objects (validators, plan
// modifiers, defaults) become {type, description, params} with unexported closure
// state read via unsafe, structs become field maps with empty values omitted, and
// RequiresReplace plan modifiers derive force_new.
func fwWalk(v reflect.Value, depth int) any {
	if !v.IsValid() || depth > 14 {
		return nil
	}

	switch v.Kind() {
	case reflect.Interface:
		if v.IsNil() {
			return nil
		}
		if desc, ok := fwDescription(v); ok {
			m := map[string]any{"type": v.Elem().Type().String()}
			if desc != "" {
				m["description"] = desc
			}
			if params, ok := fwWalk(v.Elem(), depth+1).(map[string]any); ok && len(params) > 0 {
				m["params"] = params
			}
			return m
		}
		inner := fwWalk(v.Elem(), depth+1)
		// keep the concrete kind visible for attributes/blocks (StringAttribute, ...)
		if m, ok := inner.(map[string]any); ok {
			if t := v.Elem().Type(); t.Kind() == reflect.Struct && t.Name() != "" {
				m["kind"] = t.Name()
			}
		}
		return inner
	case reflect.Ptr:
		if v.IsNil() {
			return nil
		}
		return fwWalk(v.Elem(), depth+1)
	case reflect.Struct:
		if v.CanInterface() && v.Type().Implements(fwStringerT) {
			return v.Interface().(fmt.Stringer).String()
		}

		// make an addressable copy so unexported fields are readable via unsafe
		av := v
		if v.CanInterface() {
			av = reflect.New(v.Type()).Elem()
			av.Set(v)
		}

		m := map[string]any{}
		for i := range av.NumField() {
			ft := av.Type().Field(i)
			fv := av.Field(i)
			if !ft.IsExported() {
				if !fv.CanAddr() {
					continue
				}
				fv = reflect.NewAt(fv.Type(), unsafe.Pointer(fv.UnsafeAddr())).Elem()
			}
			if val := fwWalk(fv, depth+1); val != nil {
				m[fwSnake(ft.Name)] = val
			}
		}

		if mods, ok := m["plan_modifiers"].([]any); ok {
			for _, mod := range mods {
				if mm, ok := mod.(map[string]any); ok {
					if ts, ok := mm["type"].(string); ok && strings.Contains(strings.ToLower(ts), "requiresreplace") {
						m["force_new"] = true
					}
				}
			}
		}

		if len(m) == 0 {
			return nil
		}
		return m
	case reflect.Map:
		if v.Len() == 0 {
			return nil
		}
		m := map[string]any{}
		iter := v.MapRange()
		for iter.Next() {
			if val := fwWalk(iter.Value(), depth+1); val != nil {
				m[fmt.Sprintf("%v", iter.Key().Interface())] = val
			}
		}
		return m
	case reflect.Slice, reflect.Array:
		if v.Len() == 0 {
			return nil
		}
		out := make([]any, 0, v.Len())
		for i := range v.Len() {
			if val := fwWalk(v.Index(i), depth+1); val != nil {
				out = append(out, val)
			}
		}
		if len(out) == 0 {
			return nil
		}
		return out
	case reflect.Bool:
		if v.Bool() {
			return true
		}
	case reflect.String:
		if s := v.String(); s != "" {
			return s
		}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		if i := v.Int(); i != 0 {
			return i
		}
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		if u := v.Uint(); u != 0 {
			return u
		}
	case reflect.Float32, reflect.Float64:
		if f := v.Float(); f != 0 {
			return f
		}
	}

	return nil
}

// fwDescription calls Description(ctx) string when the interface carries one -
// validators, plan modifiers and defaults all do.
func fwDescription(v reflect.Value) (string, bool) {
	m := v.MethodByName("Description")
	if !m.IsValid() {
		return "", false
	}
	mt := m.Type()
	if mt.NumIn() != 1 || mt.In(0) != fwContextT || mt.NumOut() != 1 || mt.Out(0).Kind() != reflect.String {
		return "", false
	}
	return m.Call([]reflect.Value{fwCtxV})[0].String(), true
}

func fwSnake(name string) string {
	var b strings.Builder
	for i, r := range name {
		if r >= 'A' && r <= 'Z' {
			if i > 0 {
				b.WriteByte('_')
			}
			b.WriteRune(r - 'A' + 'a')
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}
`
